@layer components {
  .button {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    background-color: var(--c-variant);
    color: inherit;
    font-weight: 700;
    letter-spacing: 0.025em;
    text-decoration: none;

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    &:not(:disabled):hover {
      border-radius: var(--radius-alt);
      background-color: color-mix(in oklch, var(--c-variant) 85%, white);
    }
    &:not(:disabled):active {
      transform: translate(0.25rem, 0.25rem);
      box-shadow: 0 0 0 var(--c-shadow);
    }

    &.sDefault {
      padding: 0.5rem 1.5rem;
      height: 2.75rem;
    }
    &.sSm {
      padding-inline: 1rem;
      height: 2.25rem;
      font-size: 0.875rem;
      line-height: 1.25rem;
    }
    &.sLg {
      padding-inline: 2rem;
      height: 3.5rem;
      font-size: 1.125rem;
      line-height: 1.75rem;
    }
    &.sIcon {
      width: 2.75rem;
      height: 2.75rem;
    }
  }
}

import { useCachedStyles } from '@/hook/useCachedStyles';
import { getCommonProps, type CommonPropsWithAs, type WithVariant } from '@/lib/utils';
import commonClasses from '@/style/common.module.css';
import type { ElementType } from 'react';
import classes from './button.module.css';

type Size = 'default' | 'sm' | 'lg' | 'icon';
const sizeClasses: Record<Size, string> = {
  default: classes.sDefault,
  sm: classes.sSm,
  lg: classes.sLg,
  icon: classes.sIcon,
};

const BUTTON_CLASSES = `${commonClasses.base} ${commonClasses.shadow} ${commonClasses.focusable} ${classes.button}`;
export function Button<E extends ElementType = 'button'>({
  as,
  size = 'default',
  style,
  ...props
}: WithVariant<CommonPropsWithAs<E, { size?: Size }>>) {
  const Comp = as ?? 'button';
  const cStyles = useCachedStyles();

  return (
    <Comp
      style={{ ...cStyles, ...style }}
      {...getCommonProps({ variant: 'primary', ...props }, BUTTON_CLASSES, sizeClasses[size])}
    />
  );
}
